gdjs.TrainingSceneCode.userFunc0xcc7958 = function GDJSInlineCode(runtimeScene) {
"use strict";
const game = runtimeScene.getGame();
const controllerKey = '__lockLootMusicController';
if (!game[controllerKey]) {
  const musicChannel = 20;
  const forcedMainTrack = { name: 'music_main_always', style: 'Neutral' };
  const mainTracks = [
    { name: 'music_main_accordion_1', style: 'Akkordeon' },
    { name: 'music_main_accordion_2', style: 'Akkordeon' },
    { name: 'music_main_marimba_1', style: 'Marimba' },
    { name: 'music_main_marimba_2', style: 'Marimba' }
  ];
  const puzzleTracks = [
    { name: 'music_puzzle_accordion_1', style: 'Akkordeon' },
    { name: 'music_puzzle_accordion_2', style: 'Akkordeon' },
    { name: 'music_puzzle_accordion_3', style: 'Akkordeon' },
    { name: 'music_puzzle_accordion_4', style: 'Akkordeon' },
    { name: 'music_puzzle_acoustic_1', style: 'Akustik' },
    { name: 'music_puzzle_acoustic_2', style: 'Akustik' },
    { name: 'music_puzzle_acoustic_3', style: 'Akustik' },
    { name: 'music_puzzle_acoustic_4', style: 'Akustik' },
    { name: 'music_puzzle_marimba_1', style: 'Marimba' },
    { name: 'music_puzzle_marimba_2', style: 'Marimba' },
    { name: 'music_puzzle_marimba_3', style: 'Marimba' },
    { name: 'music_puzzle_marimba_4', style: 'Marimba' },
    { name: 'music_puzzle_marimba_5', style: 'Marimba' },
    { name: 'music_puzzle_marimba_6', style: 'Marimba' }
  ];
  const state = { currentTrack: null, recentTracks: [], lastStyle: '', puzzleTracksRemaining: 2, wasPlaying: false, lastStartAttempt: 0, mainMenuScene: null, error: '' };
  const chooseTrack = pool => {
    const eligible = pool.filter(track => track.style !== state.lastStyle && !state.recentTracks.includes(track.name));
    if (eligible.length === 0) { state.error = 'Keine Musik erfüllt Stil- und Wiederholungsschutz.'; return null; }
    return eligible[Math.floor(Math.random() * eligible.length)];
  };
  const rememberTrack = track => {
    state.recentTracks.unshift(track.name);
    state.recentTracks = state.recentTracks.slice(0, 5);
    state.lastStyle = track.style;
  };
  const startTrack = (scene, track, remember) => {
    if (!track) return;
    if (remember) rememberTrack(track);
    state.currentTrack = track;
    state.wasPlaying = false;
    state.lastStartAttempt = Date.now();
    gdjs.evtTools.sound.playMusicOnChannel(scene, track.name, musicChannel, false, 70, 1);
  };
  const startNextTrack = scene => {
    let nextTrack = null;
    if (state.puzzleTracksRemaining > 0) {
      nextTrack = chooseTrack(puzzleTracks);
      if (nextTrack) state.puzzleTracksRemaining--;
    } else {
      nextTrack = chooseTrack(mainTracks);
      if (nextTrack) state.puzzleTracksRemaining = 2;
    }
    startTrack(scene, nextTrack, true);
  };
  const forceMain = scene => {
    gdjs.evtTools.sound.stopMusicOnChannel(scene, musicChannel);
    state.recentTracks = [];
    state.lastStyle = '';
    state.puzzleTracksRemaining = 2;
    state.error = '';
    startTrack(scene, forcedMainTrack, true);
  };
  const update = scene => {
    if (!state.currentTrack || state.error) return;
    const playing = gdjs.evtTools.sound.isMusicOnChannelPlaying(scene, musicChannel);
    if (playing) { state.wasPlaying = true; return; }
    if (state.wasPlaying) { state.wasPlaying = false; startNextTrack(scene); return; }
    if (Date.now() - state.lastStartAttempt >= 1500) {
      state.lastStartAttempt = Date.now();
      gdjs.evtTools.sound.playMusicOnChannel(scene, state.currentTrack.name, musicChannel, false, 70, 1);
    }
  };
  game[controllerKey] = { state, forceMain, update };
}
const controller = game[controllerKey];
if (!controller.state.currentTrack) controller.forceMain(runtimeScene);
controller.update(runtimeScene);
};
gdjs.TrainingSceneCode.userFunc0x9e1370 = function GDJSInlineCode(runtimeScene) {
"use strict";
// L&L-023: Rein visuelle Steuerung der modularen TrainingScene.
// Rätsel-, Hinweis-, Ressourcen- und Schlosslogik werden nur gelesen und nicht ersetzt.
// L&L-031: Große Einzelhinweise erhalten zusätzliche Innenabstände; Zähler und Blätterpfeile bleiben vollständig innerhalb der dynamischen Sprechblase.
if (!runtimeScene.__lockLootTrainingVisualState) {
  runtimeScene.__lockLootTrainingVisualState = {
    blinkTime: 0,
    mouthTime: 0,
    waveTime: 0,
    flyTime: 0,
    nextActivity: 6 + Math.random() * 6,
    activityTime: 0,
    activityElapsed: 0,
    activityMode: ""
  };
}

const visualState = runtimeScene.__lockLootTrainingVisualState;
const elapsedSeconds = Math.min(runtimeScene.getElapsedTime() / 1000, 0.05);
const success = runtimeScene.getVariables().get("rihtCode").getAsBoolean();
visualState.blinkTime = (visualState.blinkTime + elapsedSeconds) % 5.6;
visualState.mouthTime = (visualState.mouthTime + elapsedSeconds) % 0.32;
visualState.waveTime += elapsedSeconds;

const wrapParagraph = (paragraph, maxCharacters) => {
  const words = paragraph.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return [""];
  const lines = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? line + " " + word : word;
    if (candidate.length <= maxCharacters || line.length === 0) {
      line = candidate;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  return lines;
};

let hintIsSpeaking = false;
const hintObjects = runtimeScene.getObjects("txtHint");
const bubbleObjects = runtimeScene.getObjects("SpeechBubble");
const hintCounterObjects = runtimeScene.getObjects("txtHintCounter");
const hintPrevObjects = runtimeScene.getObjects("HintPrevButton");
const hintNextObjects = runtimeScene.getObjects("HintNextButton");
const hintSceneVariables = runtimeScene.getVariables();
const paidNormalHints = Math.max(0, Math.min(10, Math.floor(hintSceneVariables.get("paidHintCount").getAsNumber()) * 2));
const bonusHintVisible = hintSceneVariables.get("bonusHintActive").getAsBoolean();
let displayedHintIndex = Math.floor(hintSceneVariables.get("displayedHintIndex").getAsNumber());
if (paidNormalHints > 0) {
  displayedHintIndex = Math.max(0, Math.min(paidNormalHints - 1, displayedHintIndex));
  hintSceneVariables.get("displayedHintIndex").setNumber(displayedHintIndex);
}
const normalHintNavigationVisible = paidNormalHints > 0 && !bonusHintVisible;
if (hintObjects.length > 0 && bubbleObjects.length > 0) {
  const hint = hintObjects[0];
  const bubble = bubbleObjects[0];
  const currentText = hint.getString();
  const normalizedText = currentText.replace(/\s+/g, " ").trim();
  const textLength = normalizedText.length;
  let bubbleWidth = 432;
  let bubbleHeight = 190;
  let maxCharacters = 30;
  let hintX = 58;
  let hintY = 128;
  let hintCharacterSize = 19;
  let hintLineHeight = 24;
  let hintWrappingWidth = bubbleWidth - 116;
  if (textLength <= 50) {
    bubbleWidth = 360;
    bubbleHeight = 132;
    maxCharacters = 22;
    hintWrappingWidth = bubbleWidth - 116;
  } else {
    maxCharacters = 28;
    hintX = 66;
    hintY = 136;
    hintCharacterSize = 17;
    hintLineHeight = 21;
    hintWrappingWidth = bubbleWidth - 140;
    if (textLength > 82) bubbleHeight = 240;
  }
  if (textLength > 132) {
    bubbleHeight = 300;
  }
  if (normalHintNavigationVisible) bubbleHeight = Math.max(bubbleHeight, 160);
  const formattedText = currentText
    .split("\n")
    .flatMap((paragraph) => wrapParagraph(paragraph, maxCharacters))
    .join("\n");
  if (formattedText !== currentText) hint.setString(formattedText);
  bubble.setPosition(24, 104);
  bubble.setWidth(bubbleWidth);
  bubble.setHeight(bubbleHeight);
  hint.setPosition(hintX, hintY);
  hint.setCharacterSize(hintCharacterSize);
  hint.setLineHeight(hintLineHeight);
  hint.setTextAlignment("left");
  hint.setVerticalTextAlignment("top");
  hint.setWrapping(true);
  hint.setWrappingWidth(hintWrappingWidth);
  hint.setPadding(4);
  hintIsSpeaking =
    normalizedText.length > 0 &&
    !normalizedText.startsWith("Tippe mich an, um Hinweise zu erhalten");
  const controlsY = 104 + bubbleHeight - 50;
  for (const counter of hintCounterObjects) {
    counter.setPosition(110, controlsY + 10);
    counter.setWrapping(true);
    counter.setWrappingWidth(bubbleWidth - 220);
    counter.setTextAlignment("center");
    counter.setString(normalHintNavigationVisible ? "Hinweis " + (displayedHintIndex + 1) + " von " + paidNormalHints : "");
    counter.hide(!normalHintNavigationVisible);
  }
  for (const previousButton of hintPrevObjects) {
    previousButton.setPosition(52, controlsY);
    previousButton.hide(!normalHintNavigationVisible);
  }
  for (const nextButton of hintNextObjects) {
    nextButton.setPosition(24 + bubbleWidth - 128, controlsY);
    nextButton.hide(!normalHintNavigationVisible);
  }
}

if (!success && !hintIsSpeaking) {
  if (visualState.activityTime > 0) {
    visualState.activityTime = Math.max(0, visualState.activityTime - elapsedSeconds);
    visualState.activityElapsed += elapsedSeconds;
  } else {
    visualState.nextActivity -= elapsedSeconds;
    if (visualState.nextActivity <= 0) {
      visualState.activityMode = Math.random() < 0.55 ? "wing" : "preen";
      visualState.activityTime = visualState.activityMode === "wing" ? 0.9 : 2.4;
      visualState.activityElapsed = 0;
      visualState.nextActivity = 7 + Math.random() * 9;
    }
  }
} else {
  visualState.activityTime = 0;
  visualState.activityElapsed = 0;
}

const parrotBaseX = 500;
const parrotBaseY = 322;
for (const parrot of runtimeScene.getObjects("parrot")) {
  let frame = 0;
  if (success) {
    visualState.flyTime += elapsedSeconds;
    const flight = Math.min(visualState.flyTime, 2.2);
    parrot.setPosition(parrotBaseX + flight * 145, parrotBaseY - flight * 220);
    frame = Math.floor(visualState.flyTime * 8) % 2 === 0 ? 4 : 0;
    parrot.hide(visualState.flyTime > 1.65);
  } else {
    visualState.flyTime = 0;
    parrot.setPosition(parrotBaseX, parrotBaseY);
    parrot.hide(false);
    if (hintIsSpeaking) {
      frame = visualState.mouthTime < 0.16 ? 0 : 3;
    } else if (visualState.activityTime > 0 && visualState.activityMode === "wing") {
      frame = Math.floor(visualState.activityElapsed * 8) % 2 === 0 ? 4 : 0;
    } else if (visualState.activityTime > 0 && visualState.activityMode === "preen") {
      frame = 5;
    } else {
      if (visualState.blinkTime >= 5.24 && visualState.blinkTime < 5.36) frame = 1;
      if (visualState.blinkTime >= 5.36 && visualState.blinkTime < 5.48) frame = 2;
      if (visualState.blinkTime >= 5.48) frame = 1;
    }
  }
  parrot.setAnimationFrame(frame);
}

for (const cloud of runtimeScene.getObjects("TrainingCloud")) {
  cloud.setX(cloud.getX() + 6 * elapsedSeconds);
  if (cloud.getX() > 720) cloud.setX(-cloud.getWidth());
}

const waves = runtimeScene.getObjects("TrainingWave");
for (let index = 0; index < waves.length; index += 1) {
  const wave = waves[index];
  const baseX = index === 0 ? 0 : 320;
  const baseY = index === 0 ? 482 : 490;
  wave.setPosition(
    baseX + Math.sin(visualState.waveTime * 0.8 + index * 1.7) * 12,
    baseY + Math.sin(visualState.waveTime * 1.25 + index) * 3
  );
  wave.setOpacity(190 + Math.sin(visualState.waveTime + index) * 25);
}

for (const lid of runtimeScene.getObjects("Chest_Lid")) {
  lid.setY(success ? 470 : 520);
  lid.setAngle(success ? -5 : 0);
}
for (const lock of runtimeScene.getObjects("Lock_Sprite")) {
  lock.hide(success);
}
for (const sparkle of runtimeScene.getObjects("SuccessSparkle")) {
  sparkle.hide(!success);
}
for (const treasure of runtimeScene.getObjects("TrainingTreasure")) {
  treasure.hide(!success);
}


};
